    // deep blue at the bottom -> teal -> fresh green at the top
    bluegreen: ['#0d3b8c', '#1150b0', '#1668c9', '#1a84d4', '#18a0cc', '#17b7b0', '#1fc68c', '#47d26e', '#86df5e'],
