    // Penthouse's suits: green, burgundy, plum, pink, cream and yellow
    suits: ['#2f6b44', '#3f8a57', '#8a2226', '#b0373b', '#7b1f68', '#a8408f', '#e9a3b6', '#e6d9b8', '#f2df7c']
