      mouthEl.style.left = mb ? mb[0] + '%' : ''; mouthEl.style.top = mb ? mb[1] + '%' : '';
      mouthEl.style.width = mb ? mb[2] + '%' : ''; mouthEl.style.height = mb ? mb[3] + '%' : '';
