    var BOLT_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.5 1.5 3.5 13.8h6.6l-1.9 8.7L20.5 9.6h-6.7l2-8.1z" fill="#ffd21f" stroke="#e85d00" stroke-width="1.6" stroke-linejoin="round"/></svg>';
